UPDATE pm_task
SET title = #{title}, description = #{description}, assignee_id = #{assigneeId},
    status = #{status}, priority = #{priority}, estimated_hours = #{estimatedHours},
    actual_hours = #{actualHours}, start_date = #{startDate}, due_date = #{dueDate},
    progress = #{progress}, tags = #{tags}
WHERE id = #{id}
